import struct, zlib, json, os
from collections import defaultdict
from datetime import datetime, timezone
from zoneinfo import ZoneInfo

ny=ZoneInfo('America/New_York')
paths=[('/app/data/journals/shard-0.jnl',0),('/app/data/journals/shard-1.jnl',1),('/app/data/journals/shard-2.jnl',2)]

def parse_events():
    events=[]
    for path, shard_id in paths:
        data=open(path,'rb').read()
        pos=0
        while True:
            i=data.find(b'JNL1',pos)
            if i<0 or i+24>len(data): break
            ver,flags,typ,res=struct.unpack_from('<BBBB',data,i+4)
            raw_len=struct.unpack_from('<I',data,i+8)[0]
            seq=struct.unpack_from('<Q',data,i+12)[0]
            stored_crc=struct.unpack_from('<I',data,i+20)[0]
            if ver==1:
                plen=raw_len
            elif ver==2:
                plen=raw_len ^ 0xA5A5A5A5
            else:
                pos=i+1; continue
            end=i+24+plen
            if plen>10_000_000 or end>len(data):
                pos=i+1; continue
            frame=bytearray(data[i:end])
            frame[20:24]=b'\0\0\0\0'
            if (zlib.crc32(frame)&0xffffffff)!=stored_crc:
                pos=i+1; continue
            payload=data[i+24:end]
            if flags & 1:
                try: payload=zlib.decompress(payload)
                except Exception: pos=i+1; continue
            try: obj=json.loads(payload)
            except Exception: pos=i+1; continue
            events.append({'shard_id':shard_id,'seq':seq,'type':typ,'flags':flags,'payload':obj})
            pos=end
    return events

events=parse_events()
print('valid event count',len(events))
for e in events:
    print(e)

# transfer completeness
legs=defaultdict(dict)
for e in events:
    if e['type'] in (4,5):
        tid=e['payload']['transfer_id']
        legs[tid]['out' if e['type']==4 else 'in']=e
complete=set()
for tid,d in legs.items():
    if 'out' in d and 'in' in d:
        o=d['out']['payload']; n=d['in']['payload']
        if o['amount_minor']==n['amount_minor'] and o['account_id']==n['peer_account'] and n['account_id']==o['peer_account']:
            complete.add(tid)
print('complete transfers',complete)

# sort events by ts (opened_at for open, ts otherwise), shard, seq
for e in events:
    p=e['payload']
    e['ts']=p.get('ts', p.get('opened_at'))
events_sorted=sorted([e for e in events if e['ts'] is not None], key=lambda e:(e['ts'], e['shard_id'], e['seq']))

accounts={}
idem_seen=set()
held=defaultdict(list)
summary=defaultdict(lambda: defaultdict(int))

def day_for(ts):
    return datetime.fromtimestamp(ts, tz=timezone.utc).astimezone(ny).strftime('%Y-%m-%d')

def add_delta(acct_id, delta, ts):
    acct=accounts[acct_id]
    acct['balance_minor'] += delta
    summary[day_for(ts)][acct['currency']] += delta

def apply_balance_event(acct_id, delta, ts, idem_key=None):
    if idem_key is not None:
        if idem_key in idem_seen:
            return
        idem_seen.add(idem_key)
    acct=accounts.get(acct_id)
    if acct is None:
        return
    if acct['status']=='closed':
        held[acct_id].append((delta, ts))
    else:
        add_delta(acct_id, delta, ts)

for e in events_sorted:
    typ=e['type']; p=e['payload']; ts=e['ts']
    if typ==1:
        accounts[p['account_id']]={'account_id':p['account_id'],'currency':p['currency'],'balance_minor':0,'opened_at':p['opened_at'],'status':'open'}
    elif typ==2:
        apply_balance_event(p['account_id'], p['amount_minor'], ts, p.get('idempotency_key'))
    elif typ==3:
        apply_balance_event(p['account_id'], -p['amount_minor'], ts, p.get('idempotency_key'))
    elif typ==4:
        tid=p['transfer_id']
        if tid in complete:
            apply_balance_event(p['account_id'], -p['amount_minor'], ts)
    elif typ==5:
        tid=p['transfer_id']
        if tid in complete:
            apply_balance_event(p['account_id'], p['amount_minor'], ts)
    elif typ==6:
        acct=accounts.get(p['account_id'])
        if acct: acct['status']='closed'
    elif typ==7:
        acct=accounts.get(p['account_id'])
        if acct:
            acct['status']='open'
            for delta, hts in held.pop(p['account_id'], []):
                add_delta(p['account_id'], delta, hts)
    elif typ==8:
        pass

open_accounts={k:v for k,v in accounts.items() if v['status']=='open'}
print('\nOPEN ACCOUNTS')
for k in sorted(open_accounts):
    v=open_accounts[k]
    print(k, {kk:v[kk] for kk in ('account_id','currency','balance_minor','opened_at')})
print('\nSUMMARY')
for d in sorted(summary):
    print(d, dict(sorted(summary[d].items())))
print('\nPENDING')
pending=[]
for tid in sorted(legs):
    if tid in complete: continue
    d=legs[tid]
    out=d.get('out'); inn=d.get('in')
    op=out['payload'] if out else None
    ip=inn['payload'] if inn else None
    pending.append({
        'transfer_id':tid,
        'has_out':out is not None,
        'has_in':inn is not None,
        'out_account':op['account_id'] if op else ip['peer_account'],
        'in_account':ip['account_id'] if ip else op['peer_account'],
        'amount_minor':op['amount_minor'] if op else ip['amount_minor'],
    })
print(pending)
